#!/usr/bin/env node
/**
 * Attributes the bytes of a built application bundle back to the source files they came from.
 *
 * `check-dist` says what a probe costs; it cannot say *which module* the bytes belong to. Angular's
 * application builder does not emit an esbuild metafile, but it does emit a standard source map
 * when `--source-map` is passed. The generated positions in that map partition the bundle, so the
 * distance between two mapped positions is the number of generated bytes that came from the source
 * of the first one. Summing those distances gives a per-file retained-size table without running
 * the library's own code or guessing from minified names.
 *
 * ```bash
 * ng build probe --configuration=request --source-map --output-path=dist/probes/attribution
 * node scripts/bundle-attribution.mjs dist/probes/attribution/browser/main.js
 * ```
 *
 * The numbers are raw UTF-8 bytes, not gzip: a module's contribution to the gzip total depends on
 * what it is adjacent to. Use them to find what is retained, and `check-dist` for the budget.
 */
import { readFileSync } from 'node:fs';

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Decode one base64-VLQ segment. Source-map columns are deltas, so this only returns the fields. */
function decodeVlq(text) {
  const values = [];
  let value = 0;
  let shift = 0;
  for (const character of text) {
    const digit = BASE64.indexOf(character);
    if (digit < 0) throw new Error(`invalid base64 VLQ character: ${character}`);
    const continuation = digit & 32;
    value += (digit & 31) << shift;
    if (continuation) {
      shift += 5;
      continue;
    }
    const negative = value & 1;
    value >>= 1;
    values.push(negative ? -value : value);
    value = 0;
    shift = 0;
  }
  return values;
}

const bundlePath = process.argv[2];
if (!bundlePath) {
  console.error('usage: node scripts/bundle-attribution.mjs <bundle.js> [bundle.js.map]');
  process.exit(1);
}
const mapPath = process.argv[3] ?? `${bundlePath}.map`;

let bundle;
let map;
try {
  bundle = readFileSync(bundlePath, 'utf8');
  map = JSON.parse(readFileSync(mapPath, 'utf8'));
} catch (error) {
  console.error(`could not read the bundle and its source map: ${error.message}`);
  process.exit(1);
}

const lineStarts = [0];
for (let index = 0; index < bundle.length; index += 1) {
  if (bundle[index] === '\n') lineStarts.push(index + 1);
}
const lineEnd = (line) => (line + 1 < lineStarts.length ? lineStarts[line + 1] - 1 : bundle.length);

let sourceIndex = 0;
let originalLine = 0;
let originalColumn = 0;
const bytes = new Map();
const lines = map.mappings.split(';');

for (let generatedLine = 0; generatedLine < lines.length; generatedLine += 1) {
  let generatedColumn = 0;
  const segments = lines[generatedLine] ? lines[generatedLine].split(',') : [];
  const decoded = [];
  for (const segment of segments) {
    if (segment === '') continue;
    const values = decodeVlq(segment);
    generatedColumn += values[0];
    if (values.length >= 4) {
      sourceIndex += values[1];
      originalLine += values[2];
      originalColumn += values[3];
      decoded.push({ generatedColumn, sourceIndex });
    } else {
      decoded.push({ generatedColumn, sourceIndex: undefined });
    }
  }

  for (let index = 0; index < decoded.length; index += 1) {
    const segment = decoded[index];
    if (segment.sourceIndex === undefined) continue;
    const end =
      index + 1 < decoded.length
        ? decoded[index + 1].generatedColumn
        : lineEnd(generatedLine) - lineStarts[generatedLine];
    if (end <= segment.generatedColumn) continue;
    const source = map.sources[segment.sourceIndex] ?? String(segment.sourceIndex);
    bytes.set(source, (bytes.get(source) ?? 0) + (end - segment.generatedColumn));
  }
}

// The map has a `sources` entry for every module the linker saw. Only modules with generated
// bytes are retained; the rest were tree-shaken away.
const rows = [...bytes].sort((a, b) => b[1] - a[1]);
const attributed = rows.reduce((total, [, count]) => total + count, 0);
console.log(
  `${bundlePath}: ${bundle.length} bytes, ${attributed} attributed to ${rows.length} files`,
);
for (const [source, count] of rows) {
  console.log(
    `${String(count).padStart(8)}  ${(count / 1024).toFixed(2).padStart(8)} KB  ${source}`,
  );
}
